// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  interpolateColors,
  Easing,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: interFamily } = loadInter();



export type MinimalistDrainProps = Record<string, any>;

const MinimalistDrain: React.FC<MinimalistDrainProps> = ({
  backgroundColor = "#0F172A",
  transparentBackground = false,
  durationInSeconds = 8,
  fillColorFull = "#10B981",
  fillColorEmpty = "#EF4444",
  iconColor = "#F8FAFC",
  dailyBalanceText = "Daily Balance: $0.00",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Logic to prevent parser errors
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive scaling base unit
  const s = Math.min(width, height);
  const borderWidth = Math.max(4, s * 0.012);
  
  const bW = s * 0.22; // Battery width
  const bH = s * 0.45; // Battery height
  const bPadding = s * 0.015; // Inner padding
  
  const cSize = s * 0.38; // Clock size
  const gap = s * 0.12; // Flex gap
  const fontSize = s * 0.07; // Text size

  // Relative timing sequence mapped to dynamic duration
  const durationInFrames = Math.round(durationInSeconds * fps);
  
  const fillStart = durationInFrames * 0.1;
  const fillEnd = durationInFrames * 0.25;
  
  const clockFadeStart = durationInFrames * 0.3;
  const clockFadeEnd = durationInFrames * 0.4;
  
  const drainStart = durationInFrames * 0.45;
  const drainEnd = durationInFrames * 0.75;
  
  const textStart = durationInFrames * 0.75;
  const textEnd = durationInFrames * 0.85;

  // Interpolations
  const fillInProgress = interpolate(frame, [fillStart, fillEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

  // Violent drain easing: starts slow, snaps aggressively, settles.
  const drainProgress = interpolate(frame, [drainStart, drainEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.8, 0, 0.2, 1), 
  });

  // Calculate the current active fill amount (grows to 1, then drains to 0)
  const currentFill = Math.max(0, fillInProgress - drainProgress);

  // Colors mapping (only driven by drain sequence to hit red at zero)
  const currentColor = interpolateColors(drainProgress, [0, 1], [
    fillColorFull,
    fillColorEmpty,
  ]);

  // Clock Animations (Hour goes from 8 to 2, Minute does 6 full rotations)
  const clockOpacity = interpolate(frame, [clockFadeStart, clockFadeEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const clockScale = spring({
    fps,
    frame: frame - clockFadeStart,
    config: { damping: 14, mass: 0.8 },
  });

  // 240 deg = 8 o'clock, 420 deg = 2 o'clock
  const hourRotation = interpolate(drainProgress, [0, 1], [240, 420]);
  const minuteRotation = interpolate(drainProgress, [0, 1], [0, 2160]); // 6 hours * 360

  // Text Animations
  const textScale = spring({
    fps,
    frame: frame - textStart,
    config: { damping: 12, mass: 0.8 },
  });
  const textOpacity = interpolate(frame, [textStart, textEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Battery Sub-components Dimensions
  const innerRadius = (s * 0.04) - bPadding;
  const hourHandW = cSize * 0.035;
  const hourHandH = cSize * 0.22;
  const minuteHandW = cSize * 0.025;
  const minuteHandH = cSize * 0.38;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          flexDirection: "row",
          alignItems: "center",
          justifyContent: "center",
          gap,
        }}
      >
        {/* BATTERY ICON */}
        <div
          style={{
            width: bW,
            height: bH,
            border: `${borderWidth}px solid ${iconColor}`,
            borderRadius: s * 0.04,
            position: "relative",
            display: "flex",
            flexDirection: "column",
            justifyContent: "flex-end",
            padding: bPadding,
            transition: "none",
          }}
        >
          {/* Battery Top Bump */}
          <div
            style={{
              position: "absolute",
              top: -s * 0.02 - borderWidth,
              left: "50%",
              transform: "translateX(-50%)",
              width: bW * 0.35,
              height: s * 0.02,
              backgroundColor: iconColor,
              borderTopLeftRadius: s * 0.015,
              borderTopRightRadius: s * 0.015,
              transition: "none",
            }}
          />
          {/* Inner Fill */}
          <div
            style={{
              width: "100%",
              height: `${currentFill * 100}%`,
              backgroundColor: currentColor,
              borderRadius: innerRadius,
              boxShadow: currentFill > 0 ? `0 0 ${s * 0.04}px ${currentColor}80` : "none",
              transition: "none",
            }}
          />
        </div>

        {/* CLOCK ICON */}
        <div
          style={{
            width: cSize,
            height: cSize,
            border: `${borderWidth}px solid ${iconColor}`,
            borderRadius: "50%",
            position: "relative",
            opacity: clockOpacity,
            transform: `scale(${clockScale})`,
            transition: "none",
          }}
        >
          {/* Ticks */}
          {[...Array(12)].map((_, i) => (
            <div
              key={i}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                transform: `rotate(${i * 30}deg)`,
                transition: "none",
              }}
            >
              <div
                style={{
                  position: "absolute",
                  top: cSize * 0.04,
                  left: "50%",
                  transform: "translateX(-50%)",
                  width: cSize * 0.015,
                  height: i % 3 === 0 ? cSize * 0.07 : cSize * 0.04,
                  backgroundColor: iconColor,
                  borderRadius: cSize * 0.01,
                  transition: "none",
                }}
              />
            </div>
          ))}

          {/* Hour Hand Wrapper */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              transform: `rotate(${hourRotation}deg)`,
              transition: "none",
            }}
          >
            <div
              style={{
                position: "absolute",
                bottom: "50%",
                left: "50%",
                transform: "translateX(-50%)",
                width: hourHandW,
                height: hourHandH,
                backgroundColor: iconColor,
                borderRadius: hourHandW / 2,
                transition: "none",
              }}
            />
          </div>

          {/* Minute Hand Wrapper */}
          <div
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              transform: `rotate(${minuteRotation}deg)`,
              transition: "none",
            }}
          >
            <div
              style={{
                position: "absolute",
                bottom: "50%",
                left: "50%",
                transform: "translateX(-50%)",
                width: minuteHandW,
                height: minuteHandH,
                backgroundColor: iconColor,
                borderRadius: minuteHandW / 2,
                transition: "none",
              }}
            />
          </div>

          {/* Center Pivot */}
          <div
            style={{
              position: "absolute",
              top: "50%",
              left: "50%",
              transform: "translate(-50%, -50%)",
              width: cSize * 0.08,
              height: cSize * 0.08,
              backgroundColor: iconColor,
              borderRadius: "50%",
              zIndex: 10,
              transition: "none",
            }}
          />
        </div>

        {/* TEXT BLOCKS */}
        <div
          style={{
            opacity: textOpacity,
            transform: `scale(${textScale})`,
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            marginLeft: gap * 0.5,
            transition: "none",
          }}
        >
          <span
            style={{
              fontSize,
              color: iconColor,
              fontWeight: 700,
              whiteSpace: "nowrap",
              transition: "none",
              letterSpacing: "-0.02em",
            }}
          >
            {dailyBalanceText}
          </span>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default MinimalistDrain;